head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05036";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05036.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_showInfoPage_onclick
 * @description 「Ⅰ. 발행회사에 관한사항 Ⅱ. 주식워런트증권에 관한사항 Ⅲ. 유동성공급에 관한사항」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_showInfoPage_onclick = async function(e){
    try {
        await scwin.showInfoPage(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05036.btn_showInfoPage_onclick' }); }
};

/**
 * @method
 * @name btn_showInfoPage_2_onclick
 * @description 「Ⅰ. 발행회사에 관한사항 Ⅱ. 상장후 사용하고자 하는 명칭 Ⅲ. 주식워런트증권에 관한사항 Ⅳ. 경영상 중대한 사실발생여부」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_showInfoPage_2_onclick = async function(e){
    try {
        await scwin.showInfoPage(2)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05036.btn_showInfoPage_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_showInfoPage
 * @description show Info Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_showInfoPage = async function () {
    const sbmOptions = {
        id: "tx_fn_showInfoPage",
        method: "post",
        action: "/list/elwInfo.do",
        ref: "dma_showInfoPageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showInfoPage
 * @description show Info Page 처리
 * @param {String} bzCd bzCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showInfoPage = async function (bzCd) {
    const form = (document.PrelistPageForm || { elements: [] });
    $c.util.getComponent('dma_showInfoPageReq').set('bzCd', bzCd);
    form.action = '/list/elwInfo.do';
    $c.util.getComponent('dma_showInfoPageReq').set('method', 'elwInfo');
    await scwin.tx_fn_showInfoPage();
};
